contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We observe that C.deposit should: for ETH pool (baseToken==address(0)) accept ETH equal to baseTokenAmount
    // and increase address(c).balance by that amount; for ERC20 pools it must revert if msg.value>0.
    // We express this by attempting deposit in both modes and checking balances and revert behavior.

    function run(uint256[] calldata tokenIds, uint256 baseTokenAmount, bool sendEth) public payable {
        require(tokenIds.length <= 10, "limit tokens");

        // read whether c expects ETH as base token
        bool isEthPool = (c.baseToken() == address(0));

        // record pre-state
        uint256 beforePoolBalance = address(c).balance;
        // NFT balance observable: call ERC721(nft).balanceOf(address(c)) via c.nft()
        address nftAddr = c.nft();
        uint256 beforeNftBalance = 0;
        if (nftAddr != address(0)) {
            beforeNftBalance = ERC721(nftAddr).balanceOf(address(c));
        }

        bool reverted = false;

        // If we plan to send ETH, ensure this contract has enough
        if (sendEth) {
            require(address(this).balance >= baseTokenAmount, "insufficient test ETH");
        }

        // perform deposit call; according to C.deposit: if baseToken==0 then msg.value must equal baseTokenAmount, otherwise msg.value must be 0.
        if (sendEth) {
            // call with value
            try c.deposit{value: baseTokenAmount}(tokenIds, baseTokenAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // call without value
            try c.deposit(tokenIds, baseTokenAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read post-state
        uint256 afterPoolBalance = address(c).balance;
        uint256 afterNftBalance = 0;
        if (nftAddr != address(0)) {
            afterNftBalance = ERC721(nftAddr).balanceOf(address(c));
        }

        // General rule (single assert):
        // - If pool is ETH-based (isEthPool==true) and we called with sendEth==true and deposit did NOT revert,
        //   then the pool's balance increased by exactly baseTokenAmount and NFT balance increased by tokenIds.length.
        // - If pool is ETH-based and we called without sending ETH, deposit should still succeed (baseTokenAmount may be 0) and balance change equals baseTokenAmount.
        // - If pool is ERC20-based (isEthPool==false) and we attempted to send ETH (sendEth==true), deposit MUST revert.
        // We encode these as one boolean expression.

        assert(
            (
                // ETH pool cases
                isEthPool && (
                    // if not reverted then balance change equals provided baseTokenAmount and NFT count increased by tokenIds.length
                    (!reverted && afterPoolBalance == beforePoolBalance + baseTokenAmount && afterNftBalance == beforeNftBalance + tokenIds.length)
                    // or if reverted then it's allowed only when caller provided incorrect ETH amount (we don't try to characterize further)
                    || reverted
                )
            )
            ||
            (
                // ERC20 pool: sending ETH must revert; if we sent ETH then reverted must be true
                (!isEthPool && sendEth && reverted)
            )
        );
    }

    // allow receiving ETH for sending refunds
    receive() external payable {}
}

