contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We accept deposits of NFTs and optionally base token amount. For ETH pools, `ethAmount` must be provided
    // and will be forwarded when calling c.deposit{value: ethAmount}(...).
    // tokenAddr is the NFT contract address (should equal c.nft() for success) and tokenIds is array to deposit.
    // baseTokenAmount is used only when c.baseToken() != address(0).
    function run(address tokenAddr, uint256[] calldata tokenIds, uint256 baseTokenAmount, uint256 ethAmount) public payable {
        require(tokenIds.length <= 10, "limit size");

        // ensure we have enough ETH to forward if needed
        if (ethAmount > 0) {
            require(address(this).balance >= ethAmount, "insufficient balance for ethAmount");
        }

        // Read observables before the call
        address poolNft = c.nft();
        address poolBase = c.baseToken();
        uint256 beforePoolNftBalance = ERC721(poolNft).balanceOf(address(c));
        uint256 beforePoolBaseBalance = (poolBase == address(0)) ? address(c).balance : ERC20(poolBase).balanceOf(address(c));

        // Attempt the deposit and record whether it reverted
        bool reverted;
        // deposit is a state-changing top-level call
        try c.deposit{value: ethAmount}(tokenIds, baseTokenAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observables after the call
        uint256 afterPoolNftBalance = ERC721(poolNft).balanceOf(address(c));
        uint256 afterPoolBaseBalance = (poolBase == address(0)) ? address(c).balance : ERC20(poolBase).balanceOf(address(c));

        // If deposit reverted then nothing must have changed in observable balances.
        // If deposit succeeded then NFT balance must increase by number of tokenIds
        // and base token / ETH balance must increase by baseTokenAmount (or ethAmount for ETH pools).
        if (reverted) {
            assert(afterPoolNftBalance == beforePoolNftBalance && afterPoolBaseBalance == beforePoolBaseBalance);
        } else {
            // Note: only assert properties about public surface; rely on c.nft() being actual NFT contract used.
            uint256 expectedNftIncrease = tokenIds.length;
            uint256 nftIncrease = afterPoolNftBalance - beforePoolNftBalance;
            bool nftOk = (nftIncrease == expectedNftIncrease);

            uint256 expectedBaseIncrease = (poolBase == address(0)) ? ethAmount : baseTokenAmount;
            uint256 baseIncrease = afterPoolBaseBalance - beforePoolBaseBalance;

            bool baseOk = (baseIncrease == expectedBaseIncrease);

            assert(nftOk && baseOk);
        }
    }

    // Allow contract to receive ETH so it can forward ethAmount
    receive() external payable {}
}

