contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will call buy with supplied tokenIds and tokenWeights and an encoded empty MerkleMultiProof
    // The test checks: if buy returns (doesn't revert), then the change in virtual reserves matches buyQuote outputs
    function run(uint256[] calldata tokenIds, uint256[] calldata tokenWeights, uint256 msgValue) public payable {
        require(tokenIds.length == tokenWeights.length, "len");
        // ensure this contract has enough ETH if sending value
        if (msgValue > 0) require(address(this).balance >= msgValue, "bal");

        // Read reserves before
        uint128 beforeVirtualBase = c.virtualBaseTokenReserves();
        uint128 beforeVirtualNft = c.virtualNftReserves();

        // prepare an empty MerkleMultiProof (proof.proof empty, flags empty)
        C.MerkleMultiProof memory proof;
        proof.proof = new bytes32[](0);
        bool[] memory flags = new bool[](0);
        // encode into calldata struct type expected: (bytes32[] proof, bool[] flags)
        // We cannot pass memory struct directly when using calldata in caller; instead call via low-level ABI encoding

        bool reverted;
        uint256 netInputAmount;
        uint256 feeAmount;
        uint256 protocolFeeAmount;

        // attempt the call and capture revert flag
        try c.buy{value: msgValue}(tokenIds, tokenWeights, abi.decode(abi.encode(proof.proof, flags), (C.MerkleMultiProof))) returns (uint256 n, uint256 f, uint256 p) {
            reverted = false;
            netInputAmount = n;
            feeAmount = f;
            protocolFeeAmount = p;
        } catch {
            reverted = true;
        }

        // read after-values
        uint128 afterVirtualBase = c.virtualBaseTokenReserves();
        uint128 afterVirtualNft = c.virtualNftReserves();

        // compute expected weight sum using the public helper sumWeightsAndValidateProof
        // It is a public view and will revert if proof invalid. We call it in a try to get behavior.
        bool sumReverted;
        uint256 weightSum;
        try c.sumWeightsAndValidateProof(tokenIds, tokenWeights, abi.decode(abi.encode(proof.proof, flags), (C.MerkleMultiProof))) returns (uint256 w) {
            sumReverted = false;
            weightSum = w;
        } catch {
            sumReverted = true;
            weightSum = 0;
        }

        // If buy reverted, then at least one of: invalid ETH amount, proof invalid, or other checks; we cannot assert detailed cause.
        // We assert a general relation: if buy did NOT revert and sumWeightsAndValidateProof did NOT revert, then
        // - afterVirtualNft == beforeVirtualNft - weightSum
        // - afterVirtualBase == beforeVirtualBase + (netInputAmount - feeAmount - protocolFeeAmount)
        // - and netInputAmount equals what buyQuote(weightSum) returns (netInputAmount, feeAmount, protocolFeeAmount)

        // obtain buyQuote expected values for the same weightSum (call view)
        (uint256 qNet, uint256 qFee, uint256 qProtocol) = c.buyQuote(weightSum);

        assert(
            reverted || sumReverted || (
                // check nft reserves decreased by exactly weightSum
                uint256(beforeVirtualNft) == uint256(afterVirtualNft) + (sumReverted ? 0 : weightSum) &&
                // check base reserves increased by netInputAmount - fee - protocolFee
                uint256(afterVirtualBase) == uint256(beforeVirtualBase) + (qNet - qFee - qProtocol) &&
                // returned netInput/fees match buyQuote for the weightSum
                netInputAmount == qNet && feeAmount == qFee && protocolFeeAmount == qProtocol
            )
        );
